    /** 协调员：实验管理、登记、退组、揭盲申请。 */
    COORDINATOR,
    /** 审阅员：仅可普通查询、批准揭盲申请。 */
    REVIEWER
}
package com.example.starter.blind;

/**
 * 操作者身份，来源于受信任的本地测试头 X-Actor-Id / X-Role。
