@Transactional
public KitView registerKit(String experimentId, String packageNo, String treatment, String actorId) {
    ExperimentRow experiment = experimentRepository.findById(experimentId);
    if (experiment == null) throw notFound;
    if (kitRepository.findKit(experimentId, packageNo) != null) throw conflict("处理包编号已存在");
    long now = clock.nowMillis();
    KitRow row = new KitRow(0, experimentId, packageNo, treatment, "STOCK", actorId, now, null, null);
    try { kitRepository.insertKit(row); } catch (DuplicateKeyException e) { throw conflict(...); }
    return new KitView(experimentId, packageNo, "STOCK", now, null);
}

public KitView getKit(...) {
    mustFindExperiment? If experiment missing → 404 experiment; if kit missing → 404 kit.
    KitRow row = kitRepository.findKit(...); if null → notFound("处理包不存在");
    return new KitView(row.experimentId(), row.packageNo(), row.status(), row.registeredAt(), row.issuedAt());
}

@Transactional
public KitPickupView pickup(String experimentId, String participantId, String actorId) {
    ExperimentRow experiment = experimentRepository.lockById(experimentId);
    if (experiment == null) throw notFound("实验不存在");
    if ("CLOSED".equals(experiment.status())) throw conflict("实验已关闭，不能领取处理包");
    AllocationRow allocation = allocationRepository.findByExperimentAndParticipant(experimentId, participantId);
    if (allocation == null) throw notFound("参与者尚未在该实验登记");
    allocation = allocationRepository.lockById(allocation.id());  // 行锁，与退组串行
    if (!"ASSIGNED".equals(allocation.status())) throw conflict("参与者已退组，不能领取处理包");
    if (kitRepository.findPickupByAllocation(allocation.id()) != null) throw conflict("该参与者已领取过处理包");
    SeatRow seat = experimentRepository.findSeat(experimentId, allocation.blockNo(), allocation.seatNo());
    if (seat == null) throw new IllegalStateException(...);
    KitRow kit = kitRepository.findFirstStockKit(experimentId, seat.treatment());
    if (kit == null) throw new ApiException(UNPROCESSABLE_ENTITY, "当前无可用处理包");  // 消息不含代码/数量
    long now = clock.nowMillis();
    if (kitRepository.markIssued(kit.id(), allocation.id(), now) != 1) throw conflict("处理包发放竞争，请重试");
    String pickupId = "KP-" + UUID...;
    String wrapperCode = blindCodeGenerator.nextCode();
    KitPickupRow pickup = new KitPickupRow(pickupId, experimentId, participantId, allocation.id(), kit.id(), wrapperCode, actorId, now);
    try { kitRepository.insertPickup(pickup); } catch (DuplicateKeyException e) { throw conflict("领取冲突，请重试"); }
    return new KitPickupView(pickupId, experimentId, participantId, wrapperCode, now);
}
